        for (int i = 0; i < n; i++) {
            for (int w = capacity; w >= weight[i]; w--) {
                best[w] = Math.max(best[w], best[w - weight[i]] + value[i]);
            }
        }
        int answer = best[capacity];
        int used = 0;
        for (int w = 0; w <= capacity; w++) {
            if (best[w] == answer) {
                used = w;
                break;
            }
        }
        System.out.println(answer);
        System.out.println(used);
    }
}

