import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int src = sc.nextInt();
        int dst = sc.nextInt();
        int[][] edges = new int[m][3];
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int w = sc.nextInt();
            edges[i][0] = u;
            edges[i][1] = v;
            edges[i][2] = w;
            adj.get(u).add(new int[]{v, w});
            adj.get(v).add(new int[]{u, w});
        }
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        Arrays.sort(edges, (x, y) -> Integer.compare(x[2], y[2]));
        long mst = 0;
        int joined = 0;
        for (int[] e : edges) {
            int ra = e[0];
            while (parent[ra] != ra) ra = parent[ra];
            int rb = e[1];
            while (parent[rb] != rb) rb = parent[rb];
            if (ra == rb) continue;
            parent[rb] = ra;
            mst += e[2];
            joined++;
        }
        int components = 0;
        for (int i = 0; i < n; i++) {
            int r = i;
            while (parent[r] != r) r = parent[r];
            if (r == i) components++;
        }
        boolean connected = components == 1;
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        pq.add(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[1];
            if (cur[0] > dist[u]) continue;
            for (int[] e : adj.get(u)) {
                long nd = cur[0] + e[1];
                if (nd < dist[e[0]]) {
                    dist[e[0]] = nd;
                    pq.add(new long[]{nd, e[0]});
                }
            }
        }
        System.out.println(connected);
        System.out.println(joined == n - 1 ? String.valueOf(mst) : "-1");
        System.out.println(dist[dst] == Long.MAX_VALUE ? "-1" : String.valueOf(dist[dst]));
        System.out.println(components);
    }
}
